/* Minimal local Bootstrap-compatible interaction bundle used by RedVecinal. */
document.addEventListener('click',function(e){var close=e.target.closest('[data-dismiss-alert]');if(close){var a=close.closest('.alert');if(a)a.remove()}var open=e.target.closest('[data-modal-open]');if(open){var m=document.getElementById(open.getAttribute('data-modal-open'));if(m){m.hidden=false;document.body.style.overflow='hidden'}}var modalClose=e.target.closest('[data-modal-close]');if(modalClose){var modal=modalClose.closest('.modal');if(modal){modal.hidden=true;document.body.style.overflow=''}}if(e.target.classList&&e.target.classList.contains('modal')){e.target.hidden=true;document.body.style.overflow=''}});

